.navbar {
  overflow: hidden;
  background-color: #333;
}
.navbar a {
  float: left;
  padding: 14px 16px;
  color: white;
  text-decoration: none;
}

.dropdown-content {
  display: none;
  position: absolute;
  width: 100%;
  left: 0;
  box-shadow: 0px 8px 16px rgba(0,0,0,0.2);
}
.dropdown:hover .dropdown-content {
  display: block;
}

.column {
  float: left;
  width: 33.33%;
  padding: 10px;
}
.row:after {
  content: "";
  display: table;
  clear: both;
}
